def flatten_list(collection):
    """
    Flatten a multi-level collection (lists, tuples, sets) into a single-level list.
    Strings and bytes are treated as atomic and not flattened.

    Args:
        collection: A multi-level collection containing nested iterables.

    Returns:
        A single-level list with all nested elements flattened.
    """
    result = []

    def _flatten(item):
        if isinstance(item, (str, bytes)):
            result.append(item)
        elif isinstance(item, (list, tuple, set)):
            for elem in item:
                _flatten(elem)
        else:
            result.append(item)

    _flatten(collection)
    return result

