    # Calculate flips required if starting with '0'
    flips_start_0 = 0
    # Calculate flips required if starting with '1'
    flips_start_1 = 0

    for i, char in enumerate(s):
        expected_char_0 = '0' if i % 2 == 0 else '1'
        expected_char_1 = '1' if i % 2 == 0 else '0'

