def next_smallest_palindrome(num: int) -> int:
    """
    Return the smallest palindrome strictly greater than the input number `num`.
    """
    def is_palindrome(x: int) -> bool:
        s = str(x)
        return s == s[::-1]

    def next_palindrome(s: str) -> str:
        n = len(s)
        half = (n + 1) // 2
        left = s[:half]
        if n % 2 == 0:
            palindrome = left + left[::-1]
        else:
            palindrome = left + left[:-1][::-1]

        if palindrome > s:
            return palindrome

        # Increment the left half and form palindrome again
        left_as_num = int(left) + 1
        left = str(left_as_num)
        if len(left) > half:  # e.g., 999 + 1 = 1000 increases length
            # palindrome will be 1 followed by zeros and 1 at end
            return '1' + ('0' * (n - 1)) + '1'
        if n % 2 == 0:
            return left + left[::-1]
        else:
            return left + left[:-1][::-1]

    num += 1  # strictly greater than input
    s = str(num)
    while True:
        p = next_palindrome(s)
        if int(p) >= num:
            return int(p)
        num = int(p) + 1
        s = str(num)

