def smallest_missing(arr):
    """
    Given a sorted (ascending) list of integers, return the smallest non-negative integer
    that is not present in the list.
    """
    expected = 0
    for num in arr:
        if num < expected:
            continue
        if num == expected:
            expected += 1
        else:
            # num > expected means expected is missing
            break
    return expected

